// Authored supplementary practice. Level tags describe the intended practice band,
// not a complete CEFR syllabus or a qualification awarded by the app.
const sentence = (da, ru, note, type = 'build', daVariants = [], ruVariants = []) => ({
  da, ru, note, type, daAnswers: [da, ...daVariants], ruAnswers: [ru, ...ruVariants]
});
const gap = (da, ru, note, text, answer, wrong, daVariants = [], ruVariants = []) => ({
  ...sentence(da, ru, note, 'gap', daVariants, ruVariants),
  gap: {text, answers: Array.isArray(answer) ? answer : [answer], options: [Array.isArray(answer) ? answer[0] : answer, ...wrong]}
});
const lesson = (id, level, title, subtitle, rule, rows, kind = 'grammar', color = 'violet') => ({
  id, level, title, subtitle, rule, kind, color, icon: kind === 'grammar' ? 'layers' : 'chat',
  items: rows.map((row, index) => ({...row, id: `${id}-${index + 1}`, lessonId: id}))
});

